import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String userInput = scanner.nextLine();

        while (userInput.substring(1, userInput.length() - 1).contains("dot")) {
            int startPos = userInput.substring(1).indexOf("dot") + 1;
            userInput = userInput.substring(0, startPos) + "." + userInput.substring(startPos + 3);
        }

        int atPos = userInput.substring(1).indexOf("at") + 1;
        userInput = userInput.substring(0, atPos) + "@" + userInput.substring(atPos + 2);
        System.out.println(userInput);
    }
}
